using System.Text.Json;
using XBrowserSyncNg.Core.Crypto;
using XBrowserSyncNg.Core.Errors;
using XBrowserSyncNg.Core.I18n;
using XBrowserSyncNg.Core.Logging;

namespace XBrowserSyncNg.Core.Tests;

// Interop tests against vectors generated by the ORIGINAL JS logic
// (crypto.service.ts + lzutf8@0.6.0, see /tmp/opencode/xbs-crypto/gen-vectors.cjs).
// C# -> Node direction is verified by tools/verify-csharp-blobs.cjs.

public sealed class CryptoInteropTests
{
    private sealed record VectorCase(string name, string plainB64, string ivB64, string blob);
    private sealed record Vectors(string password, string salt, string derivedKey, List<VectorCase> cases);

    private static readonly Vectors Data = JsonSerializer.Deserialize<Vectors>(
        File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "TestData", "vectors.json")),
        new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

    private static XCryptoService Crypto() => new(new EnglishLocalizer(), new InMemoryLogger());

    [Fact]
    public void DeriveKey_MatchesNodePbkdf2()
    {
        var key = Crypto().DeriveKey(Data.password, Data.salt, "1.8.0");
        Assert.Equal(Data.derivedKey, key);
    }

    [Theory]
    [InlineData("ascii")]
    [InlineData("unicode")]
    [InlineData("bookmarks")]
    public void Decrypt_NodeBlobs(string name)
    {
        var c = Data.cases.Single(x => x.name == name);
        var expected = System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(c.plainB64));

        var actual = Crypto().Decrypt(c.blob, Data.derivedKey);

        Assert.Equal(expected, actual);
    }

    [Fact]
    public void Decrypt_WrongPassword_ThrowsInvalidCredentials()
    {
        var c = Data.cases.Single(x => x.name == "ascii");
        var wrongKey = Crypto().DeriveKey("wrong password", Data.salt, "1.8.0");

        Assert.Throws<InvalidCredentialsException>(() => Crypto().Decrypt(c.blob, wrongKey));
    }

    [Fact]
    public void EmptyString_RoundTrips_AsEmpty()
    {
        Assert.Equal(string.Empty, Crypto().Encrypt(string.Empty, Data.derivedKey));
        Assert.Equal(string.Empty, Crypto().Decrypt(string.Empty, Data.derivedKey));
    }

    [Fact]
    public void EncryptDecrypt_SelfRoundTrip_IncludingLargePayload()
    {
        var big = string.Concat(Enumerable.Repeat("abcabcabcàèìòù日本語🎉", 20_000));
        var blob = Crypto().Encrypt(big, Data.derivedKey);

        // Envelope: base64(16B IV || ciphertext+16B tag), larger than plaintext is fine.
        var raw = Convert.FromBase64String(blob);
        Assert.True(raw.Length > 16 + 16);

        Assert.Equal(big, Crypto().Decrypt(blob, Data.derivedKey));
    }

    [Fact]
    public void LegacySyncVersion_RejectedWithClearError()
    {
        Assert.Throws<UnsupportedSyncVersionException>(() => Crypto().DeriveKey("pw", "salt", null));
    }

    [Fact]
    public void LzUtf8_RoundTrip_BinaryEdgeCases()
    {
        // Bytes that stress the token format: pointer-marker range, UTF-8 leads, highs.
        var bytes = new byte[256 * 4];
        for (int i = 0; i < bytes.Length; i++)
        {
            bytes[i] = (byte)(i % 256);
        }

        Assert.Equal(bytes, LzUtf8.Decompress(LzUtf8.Compress(bytes)));
    }
}
